preConditionHook:
// CountIF counts over bars 0..N-1 INCLUDING the current bar, and the counted
// condition is a true SERIES: its own [1] offset shifts with the counted bar,
// so position i tests low[i] > low[i + 1] (EL_FEATURES `countif`, VERIFIED --
// the frozen-offset model was refuted). The counted condition is on PRICES,
// which have real history back to the chart start, so no zero-filled variable
// mirror is needed. The counts are EL numeric variables, kept as doubles.
higherLows = 0.0;
lowerHighs = 0.0;
for (ii = 0; ii < (int)lookback; ++ii) {
    if (el_gt(low[ii], low[ii + 1])) higherLows += 1;
    if (el_lt(high[ii], high[ii + 1])) lowerHighs += 1;
}
